decode(WFL_ETR_ENTRUST.ENTRUST_CLASS , '01',WFL_ETR_ENTRUST.PORTFOLIO_ID , '02', '',WFL_ETR_ENTRUST.PORTFOLIO_ID ) portfolioId, decode(WFL_ETR_ENTRUST.ENTRUST_CLASS , '01',PTL_PORTFOLIO.PORTFOLIO_NAME , '02', '',PTL_PORTFOLIO.PORTFOLIO_NAME ) portfolioName, WFL_ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN ('03', '04','T56','T93','T94','T95','T96') THEN WFL_ETR_ENTRUST.STOCK_ID else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else WFL_ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN('03','04') THEN WFL_ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN('03','04') AND WFL_ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN WFL_ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, WFL_ETR_ENTRUST.PS Ps, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = WFL_ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = WFL_ETR_ENTRUST.PS) END AS otherPs, WFL_ETR_ENTRUST_ADD.BUSI_PS busiPs, WFL_ETR_ENTRUST.TRADE_MARKET tradeMarket,
decode( btm.OUTPUT_VALUE_1, 'EX004', '', decode( WFL_ETR_ENTRUST_ADD.ASSET_TYPE, 'F01',
NVL( WFL_ETR_ENTRUST.ENTRUST_NUM * WFL_ETR_ENTRUST.PRICE, 0 ), 'F10', NVL( WFL_ETR_ENTRUST.ENTRUST_NUM * 100, 0 ), NVL( WFL_ETR_ENTRUST.ENTRUST_AMT, WFL_ETR_ENTRUST.ENTRUST_NUM ) ) )entrustAmt, decode(WFL_ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) finishAmt, WFL_ETR_ENTRUST.CCY ccy, WFL_ETR_ENTRUST.ENTRUST_DATE entrustDate, WFL_ETR_ENTRUST.VDATE vdate, WFL_ETR_ENTRUST.MDATE mdate, B.TRADER trader, B.realName realName, WFL_ETR_ENTRUST.REMARK remark, btm.OUTPUT_VALUE_1 busiTypePosition, ssai.sec_acct_name secAcctId, DECODE(WFL_ETR_ENTRUST_ADD.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, decode(WFL_ETR_ENTRUST_ADD.ASSET_TYPE,'F01','','F07',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F10',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F12',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F16',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'') termDays, round(decode(btm.OUTPUT_VALUE_1,#{busiTypePosition02},decode(WFL_ETR_ENTRUST_ADD.CALCULATE_FIELD,'price',WFL_ETR_ENTRUST.PRICE,'exerYield',WFL_ETR_ENTRUST_ADD.EXER_YIELD*100,'matureYield',WFL_ETR_ENTRUST_ADD.MATURE_YIELD*100),#{busiTypePosition03},WFL_ETR_ENTRUST.PRICE,NVL(WFL_ETR_ENTRUST.PRICE, 0.00)),4) etrPrice, DECODE(T5.ent_finish_amt,null,0, round(NVL(T5.ent_finish_amt,0)*100/(WFL_ETR_ENTRUST.ENTRUST_NUM*100),4)*100) exeProgress, DECODE(T5.FINISH_AMT,null,0, round(NVL(T5.FINISH_AMT,0)*100/(WFL_ETR_ENTRUST.ENTRUST_NUM*100),4)*100) dealProgress, NVL(T5.ent_finish_amt,0)/100 as execFinishAmt, (NVL(WFL_ETR_ENTRUST.ENTRUST_NUM,0)/100 - NVL(T5.ent_finish_amt,0)/100) as execRemainderAmt, NVL(T5.FINISH_AMT,0)/100 as transFinishAmt, (NVL(WFL_ETR_ENTRUST.ENTRUST_NUM,0)/100 - NVL(T5.FINISH_AMT,0)/100) as transRemainderAmt, NULL transmitTime, NULL transmitTimeSer, WFL_ETR_ENTRUST.PRICE_MODEL priceModel, c1.acctName trdAcctId, WFL_ETR_ENTRUST.ENTRUST_NUM entrustNum, WFL_ETR_ENTRUST_ADD.CALCULATE_FIELD calculateField FROM (SELECT * FROM WFL_ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) WFL_ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = WFL_ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = WFL_ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN WFL_ETR_ENTRUST_ADD ON WFL_ETR_ENTRUST.ENTRUST_ID = WFL_ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON WFL_ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON (WFL_ETR_ENTRUST.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 is null) AND (WFL_ETR_ENTRUST.Ps = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 is null) AND (WFL_ETR_ENTRUST.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL)
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT,SUM(Ent_Finish_Amt) as Ent_Finish_Amt FROM ETR_FINISH_STATUS where ENTRUST_ID = TRADE_ID GROUP BY ENTRUST_ID) T5 ON WFL_ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON WFL_ETR_ENTRUST_ADD.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN ( SELECT DISTINCT ACCT_NO acctNo1, BUSI_ACCT_NO busiAcctNo1, CCY ccy, ACCT_NAME acctName FROM STL_CAPACCT_INFO ) c1 ON ssai.TRD_ACCT_ID = c1.acctNo1 LEFT JOIN SYS_USER su1 ON WFL_ETR_ENTRUST.INV_MANAGER_ID = su1.USER_NAME
