#{item}
)
AND to_char(WFL_ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustStartDate} AND to_char(WFL_ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') <= #{entrustEndDate}
AND WFL_ETR_ENTRUST.CCY = #{ccy}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND c1.acctName = #{trdAcctId}
) t left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE='STATUS_VALID' and t.effectFlag=sdl.ITEM_CODE left join SYS_DATADICT_LIST sdl1 on sdl1.DICT_CODE='ENTRUST_STATUS' and t.entrustStatus=sdl1.ITEM_CODE left join SYS_DATADICT_LIST sdl2 on sdl2.DICT_CODE='PINAN_ASSET_TYPE' and t.finprodType2=sdl2.ITEM_CODE left join SYS_DATADICT_LIST sdl3 on sdl3.DICT_CODE='BUSI_TYPE_TG' and t.busiTypePosition=sdl3.ITEM_CODE left join SYS_DATADICT_LIST sdl4 on sdl4.DICT_CODE='PS' and t.PS=sdl4.ITEM_CODE left join SYS_DATADICT_LIST sdl5 on sdl5.DICT_CODE='TRADE_MARKET' and t.tradeMarket=sdl5.ITEM_CODE left join SYS_DATADICT_LIST sdl6 on sdl6.DICT_CODE='ACCOUNT_SPEED' and t.settleSpeed=sdl6.ITEM_CODE left join SYS_DATADICT_LIST sdl7 on sdl7.DICT_CODE='CCY' and t.ccy=sdl7.ITEM_CODE
order by t.finprodType2,t.entrustStatusOrder,t.busiTypePosition,t.ps)
order by ${sort} ${direction}

sql.where:


    (sdl.ITEM_VALUE like '%' || #{search} || '%'
        OR sdl1.ITEM_VALUE like '%' || #{search} || '%'
        OR sdl2.ITEM_VALUE like '%' || #{search} || '%'
        OR sdl3.ITEM_VALUE like '%' || #{search} || '%'
        OR sdl4.ITEM_VALUE like '%' || #{search} || '%'
        OR sdl5.ITEM_VALUE like '%' || #{search} || '%'
        OR sdl6.ITEM_VALUE like '%' || #{search} || '%'
        OR sdl7.ITEM_VALUE like '%' || #{search} || '%'
        OR t.entrustId like '%' || #{search} || '%'
        OR t.invManagerId like '%' || #{search} || '%'
        OR t.invManagerName like '%' || #{search} || '%'
        OR t.realName like '%' || #{search} || '%'
        OR t.trader like '%' || #{search} || '%'
        OR t.portfolioId like '%' || #{search} || '%'
        OR t.portfolioName like '%' || #{search} || '%'
        OR t.finprodMarketId like '%' || #{search} || '%'
        OR t.finprodAbbr like '%' || #{search} || '%'
        OR t.remark like '%' || #{search} || '%'
        OR t.secAcctId like '%' || #{search} || '%'
        OR t.entrustAmt||'' = #{search}
        OR t.etrPrice||'' = #{search}
        OR t.termDays||'' = #{search}
        OR t.exeProgress||'' = #{search}
        OR t.dealProgress||'' = #{search}
        OR TO_CHAR(t.entrustDate,'yyyy-MM-dd') ||''= #{search}
        OR TO_CHAR(t.entrustDate,'yyyy-MM-dd') ||''= #{year}||'-'||#{search}
        OR replace(TO_CHAR(t.entrustDate,'yyyy-MM-dd'),'-','/')=#{search}
        OR replace(TO_CHAR(t.entrustDate,'yyyy-MM-dd'),'-','/')=#{year}||'/'||#{search}
        OR t.transmitTimeSer = #{search}


                #{item}


    )

AND t.tradeMarket in ('03','04','12')

